// Package calibrate 是本地器具校准与证书台账：登记器具、录入证书、
// 申请使用、安排与处理校准计划、按器具核对，数据保存在本机台账文件中。
package calibrate

// Ready 表示基线可以运行。
func Ready() bool { return true }

content.content:
1	// Package calibrate 是本地器具校准与证书的本地台账。
2	//
3	// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
4	// 可以继续查询与操作，不同文件之间的数据互不相干。
5	package calibrate
6	
7	import (
8		"encoding/json"
9		"errors"
10		"fmt"
11		"math"
12		"os"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	)
18	
19	// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
20	const DateLayout = "2006-01-02"
21	
22	// Status 是器具的运行状态。
23	type Status string
24	
25	const (
26		// StatusPending 表示待校准，新登记器具的初始状态。
27		StatusPending Status = "待校准"
28		// StatusInUse 表示在用；在用本身不代表已经校准。
29		StatusInUse Status = "在用"
30		// StatusRetired 表示停用；停用不删除证书与使用记录。
31		StatusRetired Status = "停用"
32	)
33	
34	// ParseStatus 把命令行或文件中的状态文本解析为 Status。
35	func ParseStatus(s string) (Status, error) {
36		switch strings.TrimSpace(s) {
37		case string(StatusPending), "pending":
38			return StatusPending, nil
39		case string(StatusInUse), "in-use", "in_use":
40			return StatusInUse, nil
41		case string(StatusRetired), "retired":
42			return StatusRetired, nil
43		default:
44			return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
45		}
46	}
47	
48	// Instrument 是登记的器具信息。
49	type Instrument struct {
50		ID           string  `json:"id"`
51		Name         string  `json:"name"`
52		AllowedError float64 `json:"allowed_error"`
53		Status       Status  `json:"status"`
54		RegisteredAt string  `json:"registered_at"`
55	}
56	
57	// Certificate 是一张校准证书。
58	type Certificate struct {
59		Number       string  `json:"number"`
60		InstrumentID string  `json:"instrument_id"`
61		CalDate      string  `json:"cal_date"`
62		Expiry       string  `json:"expiry"`
63		Method       string  `json:"method"`
64		Error        float64 `json:"error"`
65		Summary      string  `json:"summary"`
66		CreatedAt    string  `json:"created_at"`
67	}
68	
69	// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
70	// 结论由数据计算，录入者不能自行选择。
71	func (c Certificate) Pass(allowedError float64) bool {
72		return math.Abs(c.Error) <= allowedError
73	}
74	
75	// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
76	type UsageRecord struct {
77		InstrumentID string   `json:"instrument_id"`
78		RequestedAt  string   `json:"requested_at"`
79		Allowed      bool     `json:"allowed"`
80		Reasons      []string `json:"reasons"`
81	}
82	
83	// ledgerData 是台账文件的持久化结构。
84	type ledgerData struct {
85		Version      int           `json:"version"`
86		Instruments  []Instrument  `json:"instruments"`
87		Certificates []Certificate `json:"certificates"`
88		Usage        []UsageRecord `json:"usage"`
89		Plans        []Plan        `json:"plans,omitempty"`
90	}
91	
92	// Ledger 是一份可操作的本地台账。
93	type Ledger struct {
94		path string
95		now  func() time.Time
96		data ledgerData
97	}
98	
99	// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
100	type ValidationError struct{ Msg string }
101	
102	func (e *ValidationError) Error() string { return e.Msg }
103	
104	func validationError(format string, args ...any) error {
105		return &ValidationError{Msg: fmt.Sprintf(format, args...)}
106	}
107	
108	// IsValidation 报告 err 是否为业务校验错误。
109	func IsValidation(err error) bool {
110		var v *ValidationError
111		return errors.As(err, &v)
112	}
113	
114	// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
115	type ConflictError struct{ Msg string }
116	
117	func (e *ConflictError) Error() string { return e.Msg }
118	
119	// IsConflict 报告 err 是否为冲突错误。
120	func IsConflict(err error) bool {
121		var c *ConflictError
122		return errors.As(err, &c)
123	}
124	
125	// ErrNotFound 表示编号在台账中不存在。
126	var ErrNotFound = errors.New("记录不存在")
127	
128	func cleanText(s string) (string, error) {
129		t := strings.TrimSpace(s)
130		if t == "" {
131			return "", validationError("不能留空或只有空白")
132		}
133		return t, nil
134	}
135	
136	func parseFiniteDate(s, field string) (time.Time, string, error) {
137		t := strings.TrimSpace(s)
138		if t == "" {
139			return time.Time{}, "", validationError("%s不能留空", field)
140		}
141		parsed, err := time.Parse(DateLayout, t)
142		if err != nil {
143			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
144		}
145		// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
146		// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
147		if parsed.Format(DateLayout) != t {
148			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
149		}
150		return parsed, t, nil
151	}
152	
153	func finiteNumber(v float64, field string) error {
154		if math.IsNaN(v) || math.IsInf(v, 0) {
155			return validationError("%s必须是有限数", field)
156		}
157		return nil
158	}
159	
160	// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
161	// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
162	func Open(path string) (*Ledger, error) {
163		return openAt(path, time.Now)
164	}
165	
166	func openAt(path string, now func() time.Time) (*Ledger, error) {
167		if strings.TrimSpace(path) == "" {
168			return nil, fmt.Errorf("台账文件路径不能为空")
169		}
170		l := &Ledger{
171			path: path,
172			now:  now,
173			data: ledgerData{Version: 1},
174		}
175		raw, err := os.ReadFile(path)
176		if err != nil {
177			if errors.Is(err, os.ErrNotExist) {
178				return l, nil
179			}
180			return nil, fmt.Errorf("读取台账 %s: %w", path, err)
181		}
182		if len(raw) > 0 {
183			if err := json.Unmarshal(raw, &l.data); err != nil {
184				return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
185			}
186		}
187		if l.data.Version == 0 {
188			l.data.Version = 1
189		}
190		return l, nil
191	}
192	
193	// Path 返回台账文件位置。
194	func (l *Ledger) Path() string { return l.path }
195	
196	// save 把当前台账完整写回文件：先写临时文件再原子改名，
197	// 保证无效录入中断时不会留下半份记录。
198	func (l *Ledger) save() error {
199		if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
200			return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
201		}
202		raw, err := json.MarshalIndent(l.data, "", "  ")
203		if err != nil {
204			return fmt.Errorf("序列化台账 %s: %w", l.path, err)
205		}
206		raw = append(raw, '\n')
207		tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
208		if err != nil {
209			return fmt.Errorf("为台账 %s 创建临时文件: %w", l.path, err)
210		}
211		tmpName := tmp.Name()
212		defer os.Remove(tmpName)
213		if _, err := tmp.Write(raw); err != nil {
214			tmp.Close()
215			return fmt.Errorf("写入台账 %s 的临时文件: %w", l.path, err)
216		}
217		if err := tmp.Close(); err != nil {
218			return fmt.Errorf("关闭台账 %s 的临时文件: %w", l.path, err)
219		}
220		if err := os.Rename(tmpName, l.path); err != nil {
221			return fmt.Errorf("替换台账文件 %s: %w", l.path, err)
222		}
223		return nil
224	}
225	
226	func (l *Ledger) findInstrument(id string) *Instrument {
227		for i := range l.data.Instruments {
228			if l.data.Instruments[i].ID == id {
229				return &l.data.Instruments[i]
230			}
231		}
232		return nil
233	}
234	
235	// Instrument 按编号返回登记器具的独立副本；编号不存在时返回包装了
236	// ErrNotFound 的错误。它只读取该器具自身的登记信息，不组装历史证书、
237	// 使用拒绝记录或校准计划：显示一张证书的结论只需要证书自身的测得误差
238	// 与该器具登记的允许误差，不需要完整核对结果。
239	func (l *Ledger) Instrument(id string) (*Instrument, error) {
240		inst := l.findInstrument(id)
241		if inst == nil {
242			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
243		}
244		saved := *inst
245		return &saved, nil
246	}
247	
248	func (l *Ledger) findCertificate(number string) *Certificate {
249		for i := range l.data.Certificates {
250			if l.data.Certificates[i].Number == number {
251				return &l.data.Certificates[i]
252			}
253		}
254		return nil
255	}
256	
257	// RegisterInput 是登记器具的输入。
258	type RegisterInput struct {
259		ID           string
260		Name         string
261		AllowedError float64
262	}
263	
264	// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
265	// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
266	//
267	// 只有本次保存成功，新器具才算正式登记：若台账文件无法写入或替换，明确返回
268	// 保存错误而不返回已登记的器具，台账（含同一对象随后的列出、按编号核对、
269	// 编号占用判断以及校准与使用安排）与登记前完全一致——失败的器具不出现在列表、
270	// 不占用编号，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次
271	// 提交同号合法内容仍报保存错误（不会因内存里残留的失败器具而被当成编号重复）。
272	// 恢复可写后无需重新打开台账，重新提交且保存成功才新增一件待校准器具，
273	// 登记时间、名称与允许误差均取本次成功提交的内容，不沿用失败申请；成功后
274	// 再登记同号仍按编号唯一拒绝。未通过业务校验的申请仍按原有方式拒绝，
275	// 不会因台账不可写而被混成保存失败。
276	func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
277		id, err := cleanText(in.ID)
278		if err != nil {
279			return nil, fmt.Errorf("器具编号无效：%w", err)
280		}
281		name, err := cleanText(in.Name)
282		if err != nil {
283			return nil, fmt.Errorf("器具名称无效：%w", err)
284		}
285		if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
286			return nil, err
287		}
288		if in.AllowedError < 0 {
289			return nil, validationError("允许的绝对误差不能小于零")
290		}
291		if l.findInstrument(id) != nil {
292			return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
293		}
294		inst := Instrument{
295			ID:           id,
296			Name:         name,
297			AllowedError: in.AllowedError,
298			Status:       StatusPending,
299			RegisteredAt: l.now().Format(time.RFC3339),
300		}
301		// 在独立的新切片上暂存新器具：只有原子替换台账文件成功后才提交。
302		// 写盘失败时恢复原切片，保证同一台账对象随后的列出、按编号核对与编号
303		// 占用判断都与登记前一致，失败器具也不会被之后的写盘顺带写入。
304		original := l.data.Instruments
305		staged := make([]Instrument, 0, len(original)+1)
306		staged = append(staged, original...)
307		staged = append(staged, inst)
308		l.data.Instruments = staged
309		if err := l.save(); err != nil {
310			l.data.Instruments = original
311			return nil, err
312		}
313		// 返回已保存器具的独立副本：返回结果只表示本次保存成功的内容。
314		saved := *l.findInstrument(id)
315		return &saved, nil
316	}
317	
318	// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
319	//
320	// 目标状态合法且与最后成功保存的状态不同后才写盘：若台账文件无法写入或替换，
321	// 明确返回保存错误，台账（含同一对象随后的列出、按器具核对、待办与使用判断）
322	// 与切换前完全一致——器具仍保持最后成功保存的状态，失败的目标状态既不会提前
323	// 参与使用资格判断，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时
324	// 再次提交同一目标状态仍报保存错误（不会因内存已被改成目标状态而被当成
325	// “状态未变”跳过保存返回成功）。恢复可写后无需重新打开台账，重新提交且保存
326	// 成功，新状态才生效。请求状态本来就等于最后成功保存的状态时直接成功，不写盘。
327	func (l *Ledger) SetStatus(id string, status Status) error {
328		switch status {
329		case StatusInUse, StatusRetired, StatusPending:
330		default:
331			return validationError("无效状态：只能是 在用、停用 或 待校准")
332		}
333		inst := l.findInstrument(id)
334		if inst == nil {
335			return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
336		}
337		if inst.Status == status {
338			return nil
339		}
340		// 在整份器具切片的独立副本上暂存新状态：只有原子替换台账文件成功后才
341		// 提交。写盘失败时恢复原切片，保证同一台账对象随后看到的器具状态、列出
342		// 结果、待办与使用判断都与切换前一致；再次提交相同状态仍会走到保存，
343		// 失败状态也不会被之后的写盘顺带写入。
344		original := l.data.Instruments
345		staged := make([]Instrument, len(original))
346		copy(staged, original)
347		for i := range staged {
348			if staged[i].ID == id {
349				staged[i].Status = status
350				break
351			}
352		}
353		l.data.Instruments = staged
354		if err := l.save(); err != nil {
355			l.data.Instruments = original
356			return err
357		}
358		return nil
359	}
360	
361	// CertificateInput 是录入校准证书的输入。
362	type CertificateInput struct {
363		InstrumentID string
364		Number       string
365		CalDate      string
366		Expiry       string
367		Method       string
368		Error        float64
369		Summary      string
370	}
371	
372	// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
373	// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
374	//
375	// 返回的证书只是本次已保存内容的展示副本，与台账内存储不共享内存：调用方
376	// 整理返回结果中的误差、截止日、编号或其他字段，不会改写台账里的正式证书，
377	// 不影响最近证书的选择、使用资格判断与编号占用，也不会被此后的写盘带入文件；
378	// 重新查询得到的仍是实际保存的内容。
379	//
380	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
381	// 台账（含同一对象随后的查询）与录入前完全一致——失败的证书既不进入历史、
382	// 不占用证书编号或该器具当天的位置，也不会在此后其他成功操作写盘时被顺带写入；
383	// 恢复可写后重新提交同号同内容会作为新证书正常录入。
384	func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
385		instID, err := cleanText(in.InstrumentID)
386		if err != nil {
387			return nil, false, fmt.Errorf("器具编号无效：%w", err)
388		}
389		number, err := cleanText(in.Number)
390		if err != nil {
391			return nil, false, fmt.Errorf("证书编号无效：%w", err)
392		}
393		method, err := cleanText(in.Method)
394		if err != nil {
395			return nil, false, fmt.Errorf("校准方法无效：%w", err)
396		}
397		summary, err := cleanText(in.Summary)
398		if err != nil {
399			return nil, false, fmt.Errorf("摘要无效：%w", err)
400		}
401		if err := finiteNumber(in.Error, "测得误差"); err != nil {
402			return nil, false, err
403		}
404	
405		inst := l.findInstrument(instID)
406		if inst == nil {
407			return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
408		}
409	
410		_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
411		if err != nil {
412			return nil, false, err
413		}
414		_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
415		if err != nil {
416			return nil, false, err
417		}
418		// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
419		todayText := l.now().Format(DateLayout)
420		if calText > todayText {
421			return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
422		}
423		if expText <= calText {
424			return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
425		}
426	
427		if existing := l.findCertificate(number); existing != nil {
428			same := existing.InstrumentID == instID &&
429				existing.CalDate == calText &&
430				existing.Expiry == expText &&
431				existing.Method == method &&
432				existing.Summary == summary &&
433				existing.Error == in.Error
434			if !same {
435				return nil, false, &ConflictError{Msg: fmt.Sprintf(
436					"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
437			}
438			// 同号且全部业务字段一致：返回原证书，不增加历史记录。
439			// 返回独立副本：调用方对返回结果的整理不能成为改写正式证书的途径。
440			dup := *existing
441			return &dup, true, nil
442		}
443	
444		// 同一器具同一天不接受两张不同编号的证书。
445		for i := range l.data.Certificates {
446			c := &l.data.Certificates[i]
447			if c.InstrumentID == instID && c.CalDate == calText {
448				return nil, false, validationError(
449					"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
450					instID, calText, c.Number)
451			}
452		}
453	
454		cert := Certificate{
455			Number:       number,
456			InstrumentID: instID,
457			CalDate:      calText,
458			Expiry:       expText,
459			Method:       method,
460			Error:        in.Error,
461			Summary:      summary,
462			CreatedAt:    l.now().Format(time.RFC3339),
463		}
464		// 在独立的新切片上暂存新证书：只有原子替换台账文件成功后才提交。
465		// 写盘失败时恢复原切片，保证同一台账对象随后看到的历史、最近证书、
466		// 证书编号占用与同日位置都与录入前一致，且不会被之后的写盘顺带写入。
467		original := l.data.Certificates
468		staged := make([]Certificate, 0, len(original)+1)
469		staged = append(staged, original...)
470		staged = append(staged, cert)
471		l.data.Certificates = staged
472		if err := l.save(); err != nil {
473			l.data.Certificates = original
474			return nil, false, err
475		}
476		// 返回已保存证书的独立副本：返回结果只表示本次保存的内容，调用方的
477		// 后续整理不会连带改写台账内的正式证书。
478		saved := *l.findCertificate(number)
479		return &saved, false, nil
480	}
481	
482	// certificatesOf 返回某器具的证书，按校准日期从新到旧排序；日期相同时
483	// （实际业务不会允许同日多证）以证书编号排序保证结果稳定。
484	func (l *Ledger) certificatesOf(id string) []Certificate {
485		var out []Certificate
486		for _, c := range l.data.Certificates {
487			if c.InstrumentID == id {
488				out = append(out, c)
489			}
490		}
491		sort.Slice(out, func(i, j int) bool {
492			if out[i].CalDate != out[j].CalDate {
493				return out[i].CalDate > out[j].CalDate
494			}
495			return out[i].Number < out[j].Number
496		})
497		return out
498	}
499	
500	// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
501	// 最近证书与录入先后无关，补录较早证书只增加历史。
502	func (l *Ledger) LatestCertificate(id string) *Certificate {
503		cs := l.certificatesOf(id)
504		if len(cs) == 0 {
505			return nil
506		}
507		return &cs[0]
508	}
509	
510	// CertificateView 是证书及其在当前日期下的判定结果。
511	type CertificateView struct {
512		Certificate
513		Pass    bool `json:"pass"`
514		Expired bool `json:"expired"`
515	}
516	
517	func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
518		return CertificateView{
519			Certificate: c,
520			Pass:        c.Pass(allowed),
521			// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
522			Expired: today.Format(DateLayout) >= c.Expiry,
523		}
524	}
525	
526	// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
527	type UsageDecision struct {
528		InstrumentID string
529		Allowed      bool
530		Reasons      []string
531		Latest       *CertificateView
532		evaluatedAt  time.Time
533	}
534	
535	// evaluateAt 按器具状态与“最近证书”判定 now 所在本机日历日期能否使用，
536	// 并列出全部适用原因。最近证书超差或到期时不会回退到更早的合格证书。
537	// 同一次核对的各部分必须共用同一个 now，避免跨午夜时判断不一致。
538	func (l *Ledger) evaluateAt(id string, now time.Time) (*Instrument, *UsageDecision) {
539		today := now
540		inst := l.findInstrument(id)
541		if inst == nil {
542			return nil, nil
543		}
544		d := &UsageDecision{InstrumentID: id, evaluatedAt: today}
545		if inst.Status != StatusInUse {
546			d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
547		}
548		latest := l.LatestCertificate(id)
549		if latest == nil {
550			d.Reasons = append(d.Reasons, "没有校准证书")
551		} else {
552			v := viewCertificate(*latest, inst.AllowedError, today)
553			d.Latest = &v
554			if !v.Pass {
555				d.Reasons = append(d.Reasons, fmt.Sprintf(
556					"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
557					latest.Number, math.Abs(latest.Error), inst.AllowedError))
558			}
559			if v.Expired {
560				d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
561					latest.Number, latest.Expiry))
562			}
563		}
564		d.Allowed = len(d.Reasons) == 0
565		return inst, d
566	}
567	
568	// CanUse 只按当前数据评估能否使用，不留存申请记录。
569	func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
570		inst, d := l.evaluateAt(id, l.now())
571		if inst == nil {
572			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
573		}
574		return d, nil
575	}
576	
577	// cloneReasons 返回原因切片的独立副本，使对外返回的数据与台账内部存储
578	// 不共享底层数组：调用方替换、删减或补充返回结果中的原因，不会改写
579	// 已留痕的历史原因。nil 保持 nil，以维持空结果的既有表现。
580	func cloneReasons(in []string) []string {
581		if in == nil {
582			return nil
583		}
584		return append([]string(nil), in...)
585	}
586	
587	// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
588	// 与当时全部原因。未知编号报错且不新增记录。
589	//
590	// 只有本次记录保存成功，申请才算提交完成：若台账文件无法写入或替换，明确返回
591	// 保存错误而不返回评估结果，台账（含同一对象随后的全部使用记录与按器具核对中
592	// 的被拒绝记录）与申请前完全一致——本次申请的时间、允许结果与拒绝原因不进入
593	// 历史，也不会在此后其他成功操作写盘时被顺带写入；器具登记信息、证书与校准计划
594	// 不因这次失败发生变化。恢复可写后无需重新打开台账，在同一台账重新申请才会按
595	// 当时的器具状态与证书重新判断并新增一条记录。
596	func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
597		if strings.TrimSpace(id) == "" {
598			return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
599		}
600		inst, d := l.evaluateAt(id, l.now())
601		if inst == nil {
602			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
603		}
604		// 留痕使用独立副本：返回给调用方的 d.Reasons 与其后的整理操作
605		// 不能成为改写台账内历史原因的途径。
606		rec := UsageRecord{
607			InstrumentID: id,
608			RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
609			Allowed:      d.Allowed,
610			Reasons:      cloneReasons(d.Reasons),
611		}
612		if rec.Reasons == nil {
613			rec.Reasons = []string{}
614		}
615		// 在独立的新切片上暂存本次申请：只有原子替换台账文件成功后才提交。
616		// 写盘失败时恢复原切片，保证同一台账对象随后看到的全部使用记录与
617		// 按器具核对中的被拒绝记录都与申请前一致，失败申请也不会被之后的
618		// 写盘顺带写入。
619		original := l.data.Usage
620		staged := make([]UsageRecord, 0, len(original)+1)
621		staged = append(staged, original...)
622		staged = append(staged, rec)
623		l.data.Usage = staged
624		if err := l.save(); err != nil {
625			l.data.Usage = original
626			return nil, err
627		}
628		return d, nil
629	}
630	
631	// InstrumentReview 是按器具核对的完整视图。
632	type InstrumentReview struct {
633		Instrument Instrument        `json:"instrument"`
634		CanUse     bool              `json:"can_use"`
635		Reasons    []string          `json:"reasons"`
636		Latest     *CertificateView  `json:"latest"`
637		History    []CertificateView `json:"history"`
638		Rejections []UsageRecord     `json:"rejections"`
639		Plans      []PlanView        `json:"plans"`
640	}
641	
642	// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
643	// 全部历史证书、被拒绝的使用记录以及该器具当前与已结束的校准计划。
644	// 整份核对只采用核对开始时的一次本机日期：即使查询结束前跨过午夜，
645	// 能否使用、最近证书、历史证书到期判断与未结束计划标记也不会各自变成新一天。
646	// 历史拒绝原因按申请当时的冻结内容展示，不随本次采用的日期重新计算。
647	// 返回的证书、拒绝记录与计划（含改期历史）都是独立展示副本，调用方的
648	// 整理不回写台账，也不影响此前或之后分别取得的其他结果。
649	func (l *Ledger) Review(id string) (*InstrumentReview, error) {
650		// 本次核对只在开始时取一次本机时间，整份结果共用，跨午夜不分裂判断；
651		// 下一次核对会重新取当时的本机日期，不沿用本次结果。
652		now := l.now()
653		inst, d := l.evaluateAt(id, now)
654		if inst == nil {
655			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
656		}
657		r := &InstrumentReview{
658			Instrument: *inst,
659			CanUse:     d.Allowed,
660			Reasons:    d.Reasons,
661			Latest:     d.Latest,
662		}
663		if r.Reasons == nil {
664			r.Reasons = []string{}
665		}
666		today := now
667		for _, c := range l.certificatesOf(id) {
668			r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
669		}
670		for _, u := range l.data.Usage {
671			if u.InstrumentID == id && !u.Allowed {
672				// 逐条深拷贝原因：对外核对视图中的历史拒绝记录只是展示副本，
673				// 调用方的整理不能回写台账，也不能影响其他入口已取得的结果。
674				u.Reasons = cloneReasons(u.Reasons)
675				r.Rejections = append(r.Rejections, u)
676			}
677		}
678		r.Plans = l.planViews(id, today)
679		return r, nil
680	}
681	
682	// Instruments 返回全部登记器具的副本，按编号排序。
683	func (l *Ledger) Instruments() []Instrument {
684		out := append([]Instrument(nil), l.data.Instruments...)
685		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
686		return out
687	}
688	
689	// parseInstant 把带偏移的 RFC3339 时间（如申请时间、计划建立时间，可带
690	// 不同偏移或 Z）解析为实际时刻。不同文字形式（如 Z 与 +00:00）只要表示
691	// 同一绝对时刻，解析结果即相同。
692	func parseInstant(s string) (time.Time, bool) {
693		t, err := time.Parse(time.RFC3339, s)
694		if err != nil {
695			return time.Time{}, false
696		}
697		return t, true
698	}
699	
700	// UsageRecords 返回全部使用申请记录，按申请发生的实际时刻从早到晚排序。
701	//
702	// RequestedAt 是带偏移的 RFC3339 时间：同一份台账可保存于不同系统时区偏移
703	// （含 Z 与显式零偏移），排序时换算为同一基准下的绝对时刻，因此显示文字里
704	// 小时、分钟更大的记录未必更晚，跨日记录也按实际时刻排列；记录各自保存时的
705	// 偏移决定先后，查询当天的系统时区不能改变历史顺序。获准与被拒绝的申请一起
706	// 参与排序，申请结果不作为排序条件。实际时刻相同的记录按器具编号升序；同一
707	// 器具在同一时刻的多次申请保留其在台账中的原有次序，每条已保存申请都保留、
708	// 不合并。没有记录时返回空结果，只有一条时原样返回。
709	//
710	// 返回的是展示副本：申请时间保留原文字及偏移，器具编号、申请结果与拒绝原因
711	// 保持保存时的内容；整理其中原因不会改动台账内已冻结的留痕，也不会被后续
712	// 正常写盘带入文件。查询本身不新增使用申请、不写回台账。
713	func (l *Ledger) UsageRecords() []UsageRecord {
714		out := append([]UsageRecord(nil), l.data.Usage...)
715		for i := range out {
716			out[i].Reasons = cloneReasons(out[i].Reasons)
717		}
718		sort.SliceStable(out, func(i, j int) bool {
719			ti, oki := parseInstant(out[i].RequestedAt)
720			tj, okj := parseInstant(out[j].RequestedAt)
721			switch {
722			case oki && okj:
723				// 按实际时刻比较：Equal/Before 以绝对时刻为准，与记录保存时
724				// 所带的偏移及文字形式无关。
725				if !ti.Equal(tj) {
726					return ti.Before(tj)
727				}
728			case oki != okj:
729				// 时间文字无法解析的异常记录排到可解析记录之后，顺序仍确定；
730				// 正常由本台账保存的 RFC3339 记录不会走到这里。
731				return oki
732			default:
733				// 两条都无法解析时退回按原文字比较，保证结果确定。
734				if out[i].RequestedAt != out[j].RequestedAt {
735					return out[i].RequestedAt < out[j].RequestedAt
736				}
737			}
738			// 实际时刻相同：按器具编号升序；编号也相同的同一时刻多次申请由
739			// SliceStable 保留其在台账中的原有次序，不因获准/拒绝结果而变动。
740			return out[i].InstrumentID < out[j].InstrumentID
741		})
742		return out
743	}
744

