137	// cliReview 是 review --json 输出中本测试关心的字段。
138	type cliReview struct {
139		CanUse     bool     `json:"can_use"`
140		Reasons    []string `json:"reasons"`
141		Instrument struct {
142			ID     string `json:"id"`
143			Status string `json:"status"`
144		} `json:"instrument"`
145		Latest *struct {
146			Number  string  `json:"number"`
