278	func TestLatestByCalDateAndSameDayRule(t *testing.T) {
279		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
280		l := newTestLedger(t, clock)
281		mustRegister(t, l, "M-1", "万用表", 0.5)
282	
283		cert := func(number, cal string, errV float64) CertificateInput {
284			return CertificateInput{
285				InstrumentID: "M-1", Number: number, CalDate: cal,
286				Expiry: "2030-01-01", Method: "m", Error: errV, Summary: "s",
287			}
288		}
289		// 先录入较晚（合格）证书，再补录更早的超差证书：补录只增加历史，
290		// 最近证书仍按校准日期取较晚的一张。
291		mustAddCert(t, l, cert("C-NEW", "2026-09-01", 0.1))
