44	func fileExists(t *testing.T, path string) bool {
45		t.Helper()
46		_, err := os.Stat(path)
47		if err == nil {
48			return true
49		}
50		if os.IsNotExist(err) {
51			return false
52		}
53		t.Fatalf("stat %s: %v", path, err)
54		return false
55	}
